CREATE POLICY "crisis_alerts: 本人可建立" ON public."crisis_alerts" AS PERMISSIVE FOR INSERT TO PUBLIC WITH CHECK (((auth.uid() = user_id) AND (EXISTS ( SELECT 1
   FROM pro_enrollments e
  WHERE ((e.user_id = auth.uid()) AND (e.practitioner_id = crisis_alerts.practitioner_id) AND (e.module_id = crisis_alerts.module_id) AND (e.status = 'active'::text))))));

CREATE POLICY "invite_codes: owner 可讀自己模組的" ON public."invite_codes" AS PERMISSIVE FOR SELECT TO PUBLIC USING ((EXISTS ( SELECT 1
   FROM pro_modules m
  WHERE ((m.id = invite_codes.module_id) AND (m.owner_id = auth.uid())))));

CREATE POLICY "perma_scores: 專業夥伴可讀已同意個案" ON public."perma_scores" AS PERMISSIVE FOR SELECT TO PUBLIC USING ((EXISTS ( SELECT 1
   FROM pro_enrollments e
  WHERE ((e.user_id = perma_scores.user_id) AND (e.practitioner_id = auth.uid()) AND (e.status = 'active'::text) AND e.share_perma))));

